// MTD bus routes on the map. The route data itself (MTD_ROUTES, MTD_STOPS,
// MTD_FEED) is in mtd-routes.js, generated by tools/build-mtd-routes.py.
// Data provided by CUMTD.

// Routes shown the first time someone opens the app: the ones that run
// through campus. After that, the routes each person picks are remembered.
const DEFAULT_BUS_ROUTE_IDS = ["12-teal", "13-silver", "22-illini"];
// Stops only show when zoomed in this far, so the map isn't covered in dots.
const BUS_STOPS_MIN_ZOOM = 16;

// Turns an encoded polyline (Google's format, 5 decimal places) back into
// [[lat, lng], …].
function decodePolyline(encoded) {
  const points = [];
  let index = 0;
  let lat = 0;
  let lng = 0;
  while (index < encoded.length) {
    for (const which of ["lat", "lng"]) {
      let shift = 0;
      let value = 0;
      let byte;
      do {
        byte = encoded.charCodeAt(index++) - 63;
        value |= (byte & 0x1f) << shift;
        shift += 5;
      } while (byte >= 0x20);
      const delta = value & 1 ? ~(value >> 1) : value >> 1;
      if (which === "lat") lat += delta;
      else lng += delta;
    }
    points.push([lat / 1e5, lng / 1e5]);
  }
  return points;
}

// Stop id → the routes that serve it, in route order.
function routesByStop(routes) {
  const index = {};
  for (const route of routes) {
    for (const stopId of route.stops) (index[stopId] ??= []).push(route);
  }
  return index;
}

// Reads the saved route picks, keeping only routes that still exist (MTD's
// routes can change when the data is updated). With nothing saved, the
// campus routes are shown.
function parseBusRoutePicks(json, routes) {
  const known = new Set(routes.map((route) => route.id));
  let saved;
  try {
    saved = JSON.parse(json);
  } catch {
    saved = null;
  }
  if (!Array.isArray(saved)) return DEFAULT_BUS_ROUTE_IDS.filter((id) => known.has(id));
  return saved.filter((id) => typeof id === "string" && known.has(id));
}

// "Nov 17" style dates for the feed's "valid through" note, from "20261219".
function formatFeedDate(yyyymmdd) {
  const year = Number(yyyymmdd.slice(0, 4));
  const month = Number(yyyymmdd.slice(4, 6));
  const day = Number(yyyymmdd.slice(6, 8));
  return new Date(year, month - 1, day).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}
